namespace TciMeter;

/// <summary>Scale arc centerline as measured from Assets/meter.png (image pixels): y for a given x, linearly interpolated.</summary>
public sealed class Arc
{
    private readonly double[] _x, _y;
    public Arc(double[] x, double[] y) { _x = x; _y = y; }

    public double Y(double x)
    {
        if (x <= _x[0]) return _y[0];
        if (x >= _x[^1]) return _y[^1];
        var i = Array.BinarySearch(_x, x);
        if (i >= 0) return _y[i];
        i = ~i;
        var t = (x - _x[i - 1]) / (_x[i] - _x[i - 1]);
        return _y[i - 1] + t * (_y[i] - _y[i - 1]);
    }
}

